const input = $input.first()?.json ?? {};

// Webhook 调用时参数在 body；手动测试时也兼容直接传入
const payload =
  input.body && typeof input.body === 'object'
    ? input.body
    : input;

const timezone = 'Asia/Shanghai';

// ---------- 基础配置 ----------
const sourceName =
  payload.source_name || 'QIANNU_MOCK';

const sourcePlatform =
  payload.source_platform || '淘宝/天猫';

const queryShopName =
  payload.query_shop_name || null;

const collectionScope =
  payload.collection_scope || 'INCREMENTAL';

// ---------- 获取北京时间 ----------
const now = new Date();

const parts = Object.fromEntries(
  new Intl.DateTimeFormat('en-US', {
    timeZone: timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23'
  })
    .formatToParts(now)
    .filter(p => p.type !== 'literal')
    .map(p => [p.type, p.value])
);

const year = Number(parts.year);
const month = Number(parts.month);
const day = Number(parts.day);
const hour = Number(parts.hour);

// 用 UTC 只做“年月日加减”，避免本机时区干扰
function formatDateUTC(date) {
  return date.toISOString().slice(0, 10);
}

const todayDate = new Date(Date.UTC(year, month - 1, day));
const yesterdayDate = new Date(todayDate.getTime() - 24 * 60 * 60 * 1000);

const today = formatDateUTC(todayDate);
const yesterday = formatDateUTC(yesterdayDate);

// ---------- 判断采集轮次 ----------
// 正式调用时优先由影刀明确传 MORNING / AFTERNOON
// 没传时，方便手动测试：北京时间 12 点前视为上午轮
let runSlot = String(
  payload.run_slot || (hour < 12 ? 'MORNING' : 'AFTERNOON')
).toUpperCase();

if (!['MORNING', 'AFTERNOON'].includes(runSlot)) {
  throw new Error(`非法 run_slot: ${runSlot}`);
}

// ---------- 生成日期查询区间 ----------
let queryStartDate;
let queryEndDate = today;

if (runSlot === 'MORNING') {
  // 08:30：昨天 ～ 今天
  queryStartDate = yesterday;
} else {
  // 14:30：今天 ～ 今天
  queryStartDate = today;
}

return [
  {
    json: {
      status: 'READY',
      source_name: sourceName,
      source_platform: sourcePlatform,
      query_shop_name: queryShopName,
      collection_scope: collectionScope,

      timezone,
      run_slot: runSlot,

      query_start_date: queryStartDate,
      query_end_date: queryEndDate
    }
  }
];

const row = $input.first().json;

return [
  {
    json: {
      status: row.status ?? 'READY',

      source_name: row.source_name,
      source_platform: row.source_platform,
      query_shop_name: row.query_shop_name ?? null,
      collection_scope: row.collection_scope,

      timezone: row.timezone ?? 'Asia/Shanghai',
      run_slot: row.run_slot,

      query_start_date: row.query_start_date,
      query_end_date: row.query_end_date
    }
  }
];
